{
  "references": [
    {
      "id": "R1",
      "summary_ko": "핏불처럼 보이지 않으며 눈의 움직임이 부자연스럽고 매끄럽지 않음."
    },
    {
      "id": "R2",
      "summary_ko": "개의 꼬리가 극도로 빠르게 흔들리며 부자연스러움."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징과 픽셀 구조가 함께 변하여 형태·존재 변화 가능성이 감지된 구간."
    },
    {
      "id": "C2",
      "summary_ko": "머리를 내릴 때 개의 혀가 변형되고 부자연스럽게 들어가며 주둥이 속으로 부분적으로 사라짐."
    },
    {
      "id": "C3",
      "summary_ko": "머리를 오르내릴 때 개의 얼굴 무늬와 머리 구조가 다른 비율과 패턴으로 변형됨."
    },
    {
      "id": "C4",
      "summary_ko": "움직임 단계에 걸쳐 꼬리 끝부분과 말림 형태 및 구조가 일관되지 않게 변함."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "구체적인 대상이 식별되지 않은 일반적인 측정 가설이므로 동일 현상 여부를 확정할 수 없습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "외모/눈 움직임 결함과 혀의 부자연스러운 변형 및 사라짐은 서로 다른 대상과 현상을 다룹니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "눈의 부자연스러운 움직임 및 견종 불일치 결함과 머리 구조 및 얼굴 무늬의 변형은 서로 다른 이상 현상입니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "대상 부위가 눈/머리와 꼬리로 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "대상이 특정되지 않은 측정 가설로, 꼬리의 부자연스러운 흔들림과의 연관성을 단정할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "꼬리의 이상과 혀의 변형은 대상 부위가 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "꼬리의 움직임 이상과 머리/얼굴 무늬 변형은 서로 다른 대상을 설명합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "둘 다 꼬리를 다루지만, 하나는 지나치게 빠른 흔들림 움직임을 지적하고 다른 하나는 꼬리 형태 및 구조의 변형을 지적하여 핵심 결함이 다릅니다."
    }
  ]
}
